    Generic(u32),
    /// Specifically colorless mana: {C}
    Colorless(u32),
    /// Variable cost
    X,
    // Future: Hybrid(Color, Color), PhyrexianColored(Color), Snow, etc.
}

/// A complete mana cost (e.g., {2}{R}{R} for a spell).
